# Builds src\Icons.g.cs from the @fortawesome/free-solid-svg-icons npm package (only the icons Hallow Keys uses).
#   .\tools\gen-icons.ps1 -FaDir <path to node_modules\@fortawesome\free-solid-svg-icons>
param([Parameter(Mandatory)] [string]$FaDir)
$names = 'key lock lock-open credit-card id-card copy paperclip globe star folder folder-open note-sticky shield-halved dice heart-pulse gear plus trash-can magnifying-glass download upload arrows-rotate check xmark eye eye-slash clock pen user fingerprint file-export file-import print triangle-exclamation list table-cells-large puzzle-piece mobile-screen floppy-disk rotate-left wand-magic-sparkles tag clone clock-rotate-left keyboard trash-can-arrow-up file-csv terminal code certificate building-columns passport car wifi server address-card wallet hourglass-half layer-group arrow-up arrow-down link shapes file-lines vault suitcase plane briefcase gamepad users box-archive square-check sort caret-up caret-down image house ellipsis folder-plus filter user-shield' -split ' '
$ver = (Get-Content (Join-Path $FaDir 'package.json') -Raw | ConvertFrom-Json).version
$sb = New-Object Text.StringBuilder
[void]$sb.AppendLine('// Generated by tools\gen-icons.ps1 - do not edit.')
[void]$sb.AppendLine("// Icons: Font Awesome Free $ver by Fonticons, Inc. - https://fontawesome.com - licensed CC BY 4.0 (https://creativecommons.org/licenses/by/4.0/).")
[void]$sb.AppendLine('using System.Collections.Generic;'); [void]$sb.AppendLine('namespace HallowKeys'); [void]$sb.AppendLine('{'); [void]$sb.AppendLine('    public static partial class Icons'); [void]$sb.AppendLine('    {')
[void]$sb.AppendLine('        // name -> SVG path data (Font Awesome viewBox height is 512)')
[void]$sb.AppendLine('        static readonly Dictionary<string, string> Data = new Dictionary<string, string> {')
foreach ($n in $names) {
    $js = 'fa' + (($n -split '-' | ForEach-Object { $_.Substring(0, 1).ToUpper() + $_.Substring(1) }) -join '') + '.js'
    $t = Get-Content (Join-Path $FaDir $js) -Raw
    $w = [regex]::Match($t, 'var width = (\d+)').Groups[1].Value; $h = [regex]::Match($t, 'var height = (\d+)').Groups[1].Value
    $p = [regex]::Match($t, "var svgPathData = '([^']+)'").Groups[1].Value
    if (-not $p) { throw "no path for $n" }
    [void]$sb.AppendLine("            { `"$n`", `"M0 0L0 0M$w ${h}L$w $h$p`" },")
}
[void]$sb.AppendLine('        };'); [void]$sb.AppendLine('    }'); [void]$sb.AppendLine('}')
[IO.File]::WriteAllText((Join-Path $PSScriptRoot '..\src\Icons.g.cs'), $sb.ToString(), (New-Object Text.UTF8Encoding($true)))
"Wrote $($names.Count) icons (Font Awesome Free $ver)"
